from pathlib import Path

for store in ('mb-dryfit','mb-for-her'):
 root=Path('stores')/store/'worker'
 storefront=root/'storefront.html'
 html=storefront.read_text()
 nav='<nav class="main-nav" aria-label="Navegação principal">'
 a=html.find(nav);b=html.find('</nav>',a)
 if a<0 or b<0:raise SystemExit('Menu superior inesperado: '+store)
 html=html[:a]+html[b+6:]
 css="\n /* Compact header filters; the old hero chip rows stay hidden. */\n .campaign-header .main-nav,.mbw-categories,#filters,#catalogBrandChips,.catalog-brand-chips,.brand-filter-summary,.mb-filter-fold{display:none!important}\n .mb-header-filters{display:flex;align-items:center;justify-content:center;gap:9px;flex:1;min-width:0;z-index:70}\n .mb-header-filter{position:relative;flex:0 1 auto;min-width:0}\n .mb-header-filter>summary{list-style:none;display:flex;align-items:center;gap:8px;border:1px solid var(--shop-line,#e1e3e7);border-radius:10px;background:var(--shop-panel,#fff);color:var(--shop-ink,#242730);font:700 12px/1.2 Manrope,Inter,Arial,sans-serif;min-height:37px;padding:9px 13px;white-space:nowrap;cursor:pointer}\n .mb-header-filter>summary::-webkit-details-marker{display:none}\n .mb-header-filter>summary:after{content:'⌄';font-size:16px;font-weight:500;transition:transform .25s}\n .mb-header-filter[open]>summary:after{transform:rotate(180deg)}\n .mb-header-filter[open]>summary,.mb-header-filter.is-selected>summary{border-color:var(--shop-accent,#f97316)}\n .mb-header-filter>summary:focus-visible,.mb-header-filter-clear:focus-visible,.mb-filter-choice:focus-visible{outline:2px solid var(--shop-accent,#f97316);outline-offset:2px}\n .mb-filter-roll{position:absolute;top:calc(100% + 9px);left:50%;width:min(245px,calc(100vw - 28px));transform:translateX(-50%);z-index:100;background:var(--shop-panel,#fff);color:var(--shop-ink,#242730);border:1px solid var(--shop-line,#e2e4e8);border-radius:13px;box-shadow:0 17px 45px #11192824;overflow:hidden}\n .mb-header-filter[open] .mb-filter-roll{animation:mb-paper-roll .34s cubic-bezier(.22,.75,.25,1) both;transform-origin:50% 0}\n @keyframes mb-paper-roll{0%{opacity:0;clip-path:inset(0 0 100% 0);transform:translateX(-50%) scaleY(.1)}58%{opacity:1;clip-path:inset(0 0 12% 0);transform:translateX(-50%) scaleY(1.035)}100%{opacity:1;clip-path:inset(0);transform:translateX(-50%) scaleY(1)}}\n .mb-filter-roll-title{padding:13px 15px 9px;font:750 11px Manrope,Inter,sans-serif;color:var(--shop-muted,#74777d);letter-spacing:.04em}\n .mb-filter-options{padding:0 7px 8px;max-height:min(320px,45vh);overflow-y:auto}\n .mb-filter-choice{display:flex;gap:10px;align-items:center;width:100%;text-align:left;border:0;border-radius:8px;background:transparent;color:inherit;padding:11px 9px;font:600 12px Manrope,Inter,Arial,sans-serif;cursor:pointer}\n .mb-filter-choice:hover{background:var(--shop-soft,#f6f7f8)}\n .mb-filter-choice[aria-checked=true]{background:var(--shop-soft,#f6f7f8);color:var(--shop-accent,#f97316)}\n .mb-filter-choice-mark{width:17px;height:17px;border:1px solid #a5a8af;border-radius:50%;display:grid;place-items:center;font-size:12px;flex:none}\n .mb-filter-choice[aria-checked=true] .mb-filter-choice-mark{border-color:var(--shop-accent,#f97316)}\n .mb-header-filter-clear{border:0;background:transparent;color:var(--shop-accent,#f97316);font:700 11px Manrope,Inter,Arial,sans-serif;min-height:35px;padding:5px 7px;white-space:nowrap;cursor:pointer}\n .mb-header-filter-clear[hidden]{display:none!important}\n body.favorites-page .mb-header-filters{display:none!important}\n @media(max-width:740px){.campaign-header{flex-wrap:wrap!important}.mb-header-filters{order:3;flex-basis:100%;width:100%;padding:6px 9px 10px;gap:8px;justify-content:center}.mb-header-filter>summary{font-size:11px;min-height:34px;padding:7px 10px}.mb-header-filter-clear{font-size:11px}.mb-filter-roll{left:50%;max-width:calc(100vw - 24px)}}\n @media(prefers-reduced-motion:reduce){.mb-header-filter[open] .mb-filter-roll{animation:none!important}.mb-header-filter>summary:after{transition:none!important}}\n"
 js="\n (()=>{\n const collection=document.getElementById('colecao');\n if(!collection)return;\n const host=document.createElement('div');host.id='mbHeaderFilters';host.className='mb-header-filters';host.setAttribute('aria-label','Filtros de Marca e Peça');\n collection.insertBefore(host,collection.firstElementChild);\n const distinct=values=>[...new Set(values.map(v=>String(v||'').trim()).filter(Boolean))];\n const list=value=>typeof value==='string'?distinct(value.split(/\\r?\\n/)):[];\n const make=(id,title,allLabel)=>{\n  const details=document.createElement('details');details.className='mb-header-filter';details.id=id;\n  const summary=document.createElement('summary');summary.textContent=title;summary.setAttribute('aria-label','Abrir filtro de '+title.toLowerCase());\n  const roll=document.createElement('div');roll.className='mb-filter-roll';const label=document.createElement('div');label.className='mb-filter-roll-title';label.textContent='ESCOLHA '+title.toUpperCase();\n  const options=document.createElement('div');options.className='mb-filter-options';options.setAttribute('role','radiogroup');options.setAttribute('aria-label',title);\n  roll.append(label,options);details.append(summary,roll);host.append(details);\n  details.addEventListener('toggle',()=>{if(details.open)host.querySelectorAll('details').forEach(other=>{if(other!==details)other.open=false})});\n  return {details,options,title,allLabel};\n };\n const brands=make('mbHeaderBrands','Marca','Todas as marcas');\n const pieces=make('mbHeaderPieces','Peça','Todas as peças');\n const clear=document.createElement('button');clear.type='button';clear.className='mb-header-filter-clear';clear.textContent='Limpar filtros';clear.hidden=true;host.append(clear);\n const selected=()=>({brand:typeof brandFilter==='string'?brandFilter:'',piece:typeof category==='string'?category:''});\n function paint(listing,values,value,change){\n  listing.options.replaceChildren();\n  for(const name of ['',...distinct(values)]){\n   const item=document.createElement('button');item.type='button';item.className='mb-filter-choice';item.setAttribute('role','radio');item.setAttribute('aria-checked',String(value===name));\n   const mark=document.createElement('span');mark.className='mb-filter-choice-mark';mark.setAttribute('aria-hidden','true');mark.textContent=value===name?'✓':'';\n   const text=document.createElement('span');text.textContent=name||listing.allLabel;item.append(mark,text);\n   item.addEventListener('click',()=>{change(name);listing.details.open=false;refreshLabel();if(typeof render==='function'){render.limit=60;render();}document.getElementById('colecao')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});});\n   listing.options.append(item);\n  }\n }\n let brandOptions=[],pieceOptions=[];\n function refreshLabel(){\n  const value=selected();brands.details.querySelector('summary').textContent=value.brand||'Marca';pieces.details.querySelector('summary').textContent=value.piece||'Peça';\n  brands.details.classList.toggle('is-selected',!!value.brand);pieces.details.classList.toggle('is-selected',!!value.piece);\n  clear.hidden=!(value.brand||value.piece);\n  paint(brands,brandOptions,value.brand,v=>{brandFilter=v});\n  paint(pieces,pieceOptions,value.piece,v=>{category=v});\n }\n clear.addEventListener('click',()=>{\n  brandFilter='';category='';brands.details.open=false;pieces.details.open=false;\n  const searchInput=document.getElementById('search');if(searchInput)searchInput.value='';if(typeof search==='string')search=''\n  refreshLabel();if(typeof render==='function'){render.limit=60;render();}document.getElementById('colecao')?.scrollIntoView({behavior:'smooth'});\n });\n document.addEventListener('click',event=>{if(!host.contains(event.target))host.querySelectorAll('details').forEach(d=>d.open=false)});\n document.addEventListener('keydown',event=>{if(event.key==='Escape'){host.querySelectorAll('details').forEach(d=>d.open=false)}});\n const update=settings=>{\n  const data=typeof products!=='undefined'&&Array.isArray(products)?products:[];\n  brandOptions=Object.prototype.hasOwnProperty.call(settings,'catalog_brands')?list(settings.catalog_brands):distinct(data.map(p=>p.brand));\n  pieceOptions=Object.prototype.hasOwnProperty.call(settings,'catalog_categories')?list(settings.catalog_categories):distinct(data.map(p=>p.category));\n  const current=selected();\n  if(current.brand&&!brandOptions.includes(current.brand))brandFilter='';\n  if(current.piece&&!pieceOptions.includes(current.piece))category='';\n  refreshLabel();if(typeof render==='function')render();\n };\n fetch('/api/shop/appearance',{cache:'no-store',credentials:'same-origin'})\n  .then(response=>response.ok?response.json():Promise.reject(Error('configuração indisponível')))\n  .then(data=>update(data.appearance||{})).catch(()=>update({}));\n refreshLabel();\n })();\n"
 css += "\n /* Refined filters in the free collection space, no bulky header controls. */\n #colecao .mb-header-filters{display:flex!important;justify-content:flex-end;align-items:center;flex-wrap:wrap;gap:9px;position:relative;z-index:12;width:100%;min-width:0;min-height:50px;max-width:none;margin:0 0 4px;padding:0 0 8px}\n #colecao .mb-header-filter{flex:none;position:relative}\n #colecao .mb-header-filter>summary{min-height:39px;border-radius:100px;padding:8px 16px;gap:10px;background:var(--shop-panel,#fff);border:1px solid var(--shop-line,#dfe2e8);font:700 12px Manrope,Inter,Arial,sans-serif;box-shadow:0 2px 9px #10131c08}\n #colecao .mb-header-filter>summary:hover{border-color:var(--shop-accent,#ff7429);box-shadow:0 5px 18px #10131c12}\n #colecao .mb-header-filter.is-selected>summary{background:var(--shop-soft,#fafafa);border-color:var(--shop-accent,#ff7429)}\n #colecao .mb-header-filter-clear{font-size:12px;padding:8px 10px}\n #colecao .mb-filter-roll{left:auto;right:0;width:min(255px,calc(100vw - 30px));transform:none;transform-origin:top right}\n #colecao .mb-header-filter[open] .mb-filter-roll{animation:mb-collection-paper .34s cubic-bezier(.22,.75,.25,1) both}\n @keyframes mb-collection-paper{0%{opacity:0;clip-path:inset(0 0 100% 0);transform:scaleY(.12)}65%{opacity:1;clip-path:inset(0 0 10% 0);transform:scaleY(1.035)}100%{opacity:1;clip-path:inset(0);transform:scaleY(1)}}\n #colecao #catalogBrandChips,#colecao .catalog-brand-chips,#colecao #filters,\n #colecao .brand-filter-summary,#colecao #brandFilterSummary,\n #colecao #brandFilterFold,#colecao #pieceFilterFold{display:none!important}\n /* Search now takes the old counter/chip area, on the left. */\n #colecao .catalog-toolbar{display:flex!important;flex-wrap:wrap!important;justify-content:flex-start!important;align-items:center!important;gap:10px!important;padding:9px 0 22px!important}\n #colecao .catalog-toolbar #count{display:none!important}\n #colecao .catalog-toolbar #search{display:block!important;order:0!important;margin:0!important;flex:0 1 380px!important;width:min(100%,380px)!important;max-width:100%!important;min-height:49px;border-radius:13px!important;padding:12px 17px!important}\n #colecao .catalog-toolbar #catalogFeedback:empty{display:none!important}\n body.favorites-page #colecao .mb-header-filters{display:none!important}\n @media(max-width:740px){\n  #colecao .mb-header-filters{order:initial;flex-basis:auto;justify-content:flex-start;padding:0 0 12px;min-height:44px;margin:0 0 9px}\n  #colecao .mb-header-filter>summary{padding:8px 13px;font-size:11px;min-height:38px}\n  #colecao .mb-header-filter-clear{font-size:11px}\n  #colecao .catalog-toolbar #search{width:100%!important;flex:1 1 100%!important}\n }\n @media(prefers-reduced-motion:reduce){#colecao .mb-header-filter[open] .mb-filter-roll{animation:none!important}}\n"
 if '</head>' not in html or '</body>' not in html:raise SystemExit('Catálogo não reconhecido: '+store)
 html=html.replace('</head>','<style>'+css+'</style></head>',1)
 html=html.replace('</body>','<script>'+js+'</script></body>',1)
 storefront.write_text(html)

 admin=root/'page.html'
 page=admin.read_text()
 nav_marker="['settings','⚙','Configurações']"
 render_marker="if(page==='appearance'&&owner()){renderCatalogEditor();return}"
 if nav_marker not in page or render_marker not in page:raise SystemExit('Modo dono inesperado: '+store)
 page=page.replace(nav_marker,"['catalogfilters','◫','Filtros do catálogo'],"+nav_marker,1)
 page=page.replace(render_marker,render_marker+"if(page==='catalogfilters'&&owner()){renderOwnerFilters();return}",1)
 page=page.replace("page!=='appearance'","page!=='appearance'&&page!=='catalogfilters'",1)
 style="""
 body.mb-filter-owner #appearanceEditor .editor-tool-nav,body.mb-filter-owner #appearanceEditor .editor-preview-panel,
 body.mb-filter-owner #appearanceEditor .editor-mobile-mode,
 body.mb-filter-owner #appearanceEditor [data-editor-panel]:not([data-editor-panel=catalogfilters]){display:none!important}
 body.mb-filter-owner #appearanceEditor .editor-studio{display:block!important}
 body.mb-filter-owner #appearanceEditor .editor-settings{width:100%!important;max-width:900px!important}
 .mb-filter-editor{padding:20px;border:1px solid #e0e3e9;border-radius:14px;background:white;margin:16px 0}
 .mb-filter-editor h3{margin:0 0 8px}.mb-filter-editor p{font-size:12px;color:#6d7480}
 .mb-filter-editor-row{display:flex;gap:8px;margin:8px 0}
 .mb-filter-editor-row input{flex:1;min-width:0;padding:12px;border:1px solid #d9dce4;border-radius:9px}
 .mb-filter-editor-row button,.mb-filter-editor-add{padding:10px 15px;border:1px solid #dde0e5;border-radius:9px;cursor:pointer;background:#f6f7f8}
 """
 adminjs=r"""
 async function renderOwnerFilters(){
  if(!owner())return;
  document.body.classList.add('mb-filter-owner');
  await renderCatalogEditor();
  const heading=document.querySelector('#view .heading h2');
  if(heading)heading.textContent='Filtros do catálogo';
  const sub=document.querySelector('#view .heading .sub');
  if(sub)sub.textContent='Adicione e remova marcas e tipos de peça. Salve o rascunho e publique para atualizar sua loja.';
  const form=document.getElementById('appearanceForm');
  const tab=form?.querySelector('[data-editor-section="catalogfilters"]');
  if(!tab)return;
  tab.click();
  for(const [key,name] of [['catalog_brands','Marcas'],['catalog_categories','Peças']]){
   const field=form.querySelector('[name="'+key+'"]');if(!field)continue;
   field.closest('label').hidden=true;
   const wrapper=document.createElement('div');wrapper.className='mb-filter-editor';
   const h=document.createElement('h3');h.textContent=name;
   const note=document.createElement('p');note.textContent='Uma opção por linha. Remover o filtro não apaga nenhuma peça.';
   const rows=document.createElement('div');
   const add=document.createElement('button');add.className='mb-filter-editor-add';add.type='button';add.textContent='+ Adicionar '+(key==='catalog_brands'?'marca':'peça');
   wrapper.append(h,note,rows,add);field.closest('[data-editor-panel]').append(wrapper);
   const sync=()=>{field.value=[...rows.querySelectorAll('input')].map(x=>x.value.trim()).filter(Boolean).join('\n');field.dispatchEvent(new Event('input',{bubbles:true}))};
   const row=value=>{if(rows.children.length>=24)return;const box=document.createElement('div');box.className='mb-filter-editor-row';const input=document.createElement('input');input.value=value;input.maxLength=45;input.setAttribute('aria-label','Nome da opção '+name);input.oninput=sync;const remove=document.createElement('button');remove.type='button';remove.textContent='Remover';remove.onclick=()=>{box.remove();sync()};box.append(input,remove);rows.append(box);return input};
   field.value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).forEach(row);
   add.onclick=()=>{const input=row('');input?.focus()};
  }
 }
 """
 if '</head>' not in page or '</body>' not in page:raise SystemExit('Modo dono inválido: '+store)
 page=page.replace('</head>','<style>'+style+'</style></head>',1)
 page=page.replace('</body>','<script>'+adminjs+'</script></body>',1)
 admin.write_text(page)
 print('Filtros Marca / Peça instalados:',store)
